import{_ as t,o,c as r,ag as a}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 6 Homework — Project 1, version 1","description":"","frontmatter":{"source":"weeks/06-spec-to-app/homework.md"},"headers":[],"relativePath":"weeks/06-spec-to-app/homework.md","filePath":"weeks/06-spec-to-app/homework.md"}'),i={name:"weeks/06-spec-to-app/homework.md"};function s(n,e,d,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="week-6-homework--project-1-version-1" tabindex="-1">Week 6 Homework — Project 1, version 1 <a class="header-anchor" href="#week-6-homework--project-1-version-1" aria-label="Permalink to &quot;Week 6 Homework — Project 1, version 1&quot;">​</a></h1><p><strong>Due before next week&#39;s Studio A</strong> (week 7; default 11:59 pm the night before) · <strong>Core:</strong> about 5 hours with project time, required · <strong>Stretch:</strong> optional</p><h2 id="deliverables-checklist" tabindex="-1">Deliverables checklist <a class="header-anchor" href="#deliverables-checklist" aria-label="Permalink to &quot;Deliverables checklist&quot;">​</a></h2><p>In your <strong>public Project 1 repository</strong>:</p><ul><li>☐ <code>index.html</code>, <code>style.css</code> and <code>app.js</code> in the top folder, the rules in <code>lib/</code>, the tests in <code>tests/</code>, and a <code>package.json</code> whose <code>npm test</code> runs them. No frameworks, no libraries, no build step</li><li>☐ GitHub Pages site live, passing <strong>at least half of your MUST criteria</strong></li><li>☐ At least <strong>one automated test</strong> of your pure logic passing with <code>npm test</code>, written before its code (the final version needs at least three)</li><li>☐ <code>SPEC.md</code>, revised after the bake-off</li><li>☐ <code>TESTS.md</code>: manual tests with dated results, and the automated tests table with the end of your <code>npm test</code> output</li><li>☐ <code>README.md</code> with a live link, a &quot;How it works&quot; table and an acceptance table covering every criterion</li><li>☐ <code>PROMPTS.md</code>: the builder prompt, the plan prompt, the checks and a teach-back for each step, and &quot;What I wrote or decided myself&quot;</li><li>☐ <code>docs/bake-off-scorecard.md</code>: sections 1–5 (your builder, your partner&#39;s builder, your plain version)</li><li>☐ Small commits with clear messages (at least 4 so far; the final version needs at least 6)</li></ul><p>On <strong>Canvas</strong> (private: never in your repository):</p><ul><li>☐ Your <strong>bake-off Verdict</strong>, written without AI. This is your week 6 reflection</li></ul><p>Submit your repository link and your GitHub Pages link on Canvas.</p><h2 id="time-plan" tabindex="-1">Time plan <a class="header-anchor" href="#time-plan" aria-label="Permalink to &quot;Time plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Kind</th><th>Time</th></tr></thead><tbody><tr><td>1. Build version 1 with the Safe Loop</td><td>Project time and homework</td><td>about 3 h</td></tr><tr><td>2. Revise your spec after the bake-off</td><td>Homework</td><td>15 min</td></tr><tr><td>3. Update <code>TESTS.md</code></td><td>Homework</td><td>20 min</td></tr><tr><td>4. Write your README</td><td>Homework</td><td>30 min</td></tr><tr><td>5. Finish the scorecard</td><td>Homework</td><td>15 min</td></tr><tr><td>6. Complete <code>PROMPTS.md</code></td><td>Journal</td><td>15 min</td></tr><tr><td>7. Write the Verdict</td><td>Reflection</td><td>30 min</td></tr><tr><td><strong>Total</strong></td><td></td><td><strong>about 5 h</strong></td></tr></tbody></table><p>Before next week&#39;s Studio A, also do the &quot;Before Studio A&quot; list on the <a href="./../07-read-and-debug/">week 7 page</a> (up to 30 minutes).</p><p>Version 1 doesn&#39;t have to be finished: it must pass <strong>at least half of your MUST criteria</strong>, and your README must say honestly which ones. The final is due before week 9 Studio A (<a href="./../../projects/project-1-useful-tool.html">Project 1 brief</a>, <a href="./../../assessment/rubrics.html#project-1">rubric</a>).</p><hr><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><h3 id="1-build-version-1-with-the-safe-loop-about-3-hours" tabindex="-1">1. Build version 1 with the Safe Loop (about 3 hours) <a class="header-anchor" href="#1-build-version-1-with-the-safe-loop-about-3-hours" aria-label="Permalink to &quot;1. Build version 1 with the Safe Loop (about 3 hours)&quot;">​</a></h3><p>Continue from <a href="./lab.html#part-3--start-project-1-in-a-codespace-40-min">lab Part 3</a>: reopen your Codespace from <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>, start the preview with <code>python3 -m http.server 8000</code>, open a second terminal for <code>npm test</code>, and keep going <strong>one step at a time</strong>. 🟢 AI on for the app code; 🟡 AI limited for the tests, which you write.</p><p>For every step:</p><ol><li><strong>Check first:</strong> a new rule gets its test from your logic plan, run red with <code>npm test</code>; for what the page shows, write the manual check in <code>PROMPTS.md</code>. Both before you ask for the code.</li><li><strong>Step:</strong> ask for one step of your plan.</li><li><strong>Test:</strong> <code>npm test</code>, then the preview: your manual check and one edge case. Blank page? Console first.</li><li><strong>Read and teach back:</strong> ask about anything you can&#39;t explain, then write your teach-back in <code>PROMPTS.md</code>.</li><li><strong>Commit:</strong> one commit per working step, with an <code>Assisted-by:</code> line, for example <code>Add weekly totals with tests (AC7)</code>. Push with <strong>Sync Changes</strong>.</li></ol><p>Stay inside your constraints: plain files, no frameworks or libraries, no build step, data in localStorage, no <code>document</code>, <code>localStorage</code> or clock inside <code>lib/</code>. Never let the AI change a test to make it pass. Two failed fixes for the same problem? <strong>The two-strikes rule</strong>: a fresh chat with your spec, tests and current code, plus what you tried, the exact error and what you expected (<a href="./../../resources/safe-loop.html#the-two-strikes-rule">The Safe Loop</a>). Stop your Codespace after each session.</p><p>✅ <strong>Checkpoint:</strong> your Pages site (<code>https://[your-username].github.io/[repo-name]/</code>) opens on your phone and your laptop, at least half of your MUST criteria pass <strong>there</strong>, not only in the preview, and <code>npm test</code> shows at least one passing test.</p><h3 id="2-revise-your-spec-after-the-bake-off-15-min" tabindex="-1">2. Revise your spec after the bake-off (15 min) <a class="header-anchor" href="#2-revise-your-spec-after-the-bake-off-15-min" aria-label="Permalink to &quot;2. Revise your spec after the bake-off (15 min)&quot;">​</a></h3><p>Update <code>SPEC.md</code> with what the bake-off and building taught you (a criterion two builders read differently, a new edge case, something moved to Out of scope), update &quot;Last updated&quot;, and commit with a message that says why. 🟡 AI limited: you write it.</p><h3 id="3-update-testsmd-20-min" tabindex="-1">3. Update TESTS.md (20 min) <a class="header-anchor" href="#3-update-testsmd-20-min" aria-label="Permalink to &quot;3. Update TESTS.md (20 min)&quot;">​</a></h3><ul><li>Run every manual test on your <strong>live site</strong> and fill in the Result column with the date: ✅, or what went wrong.</li><li>In <strong>Automated tests</strong>, list each test file and what it checks, then paste the last lines of your <code>npm test</code> output (the <code>pass</code> and <code>fail</code> counts).</li><li>Found a bug by testing? Log it under <strong>Bugs found by testing</strong>, with the commit that fixed it.</li></ul><h3 id="4-write-your-readme-30-min" tabindex="-1">4. Write your README (30 min) <a class="header-anchor" href="#4-write-your-readme-30-min" aria-label="Permalink to &quot;4. Write your README (30 min)&quot;">​</a></h3><p>Replace GitHub&#39;s README with one based on the <a href="./../../templates/PROJECT_README.html">Project README template</a>:</p><ul><li>Put your <strong>live site</strong> link at the top.</li><li>In <strong>How it works</strong>, list <code>index.html</code> (structure), <code>style.css</code> (appearance), <code>app.js</code> (the page and saving), <code>lib/</code> (the rules, as pure functions) and &quot;localStorage, under the key [your key]&quot; (data). For authorization: &quot;n/a: single-user app; data stays in your browser&quot;.</li><li>Replace <strong>Run it yourself</strong> with: &quot;Open the live site, or in a Codespace run <code>python3 -m http.server 8000</code> and open the forwarded port. Run the tests with <code>npm test</code>.&quot;</li><li>In <strong>Status against the spec</strong>, list <strong>every</strong> criterion from <code>SPEC.md</code>, marked ✅ passes, ⚠️ partly (say what fails) or ☐ not yet.</li><li>Delete template sections that don&#39;t apply yet (security checklist).</li></ul><h3 id="5-finish-the-scorecard-15-min" tabindex="-1">5. Finish the scorecard (15 min) <a class="header-anchor" href="#5-finish-the-scorecard-15-min" aria-label="Permalink to &quot;5. Finish the scorecard (15 min)&quot;">​</a></h3><p>Copy your completed <a href="./bake-off-scorecard.html">bake-off scorecard</a>, sections 1–5, into your repository as <code>docs/bake-off-scorecard.md</code> (typing <code>docs/bake-off-scorecard.md</code> as the new file&#39;s name creates the folder), and fill in the &quot;My plain version&quot; column on your live site.</p><h3 id="6-complete-promptsmd-15-min" tabindex="-1">6. Complete PROMPTS.md (15 min) <a class="header-anchor" href="#6-complete-promptsmd-15-min" aria-label="Permalink to &quot;6. Complete PROMPTS.md (15 min)&quot;">​</a></h3><p>Your <code>PROMPTS.md</code> should now hold, as well as last week&#39;s Goldfish runs:</p><ul><li>the builder prompt, and one thing your builder got wrong;</li><li>the Describe/Plan prompt for your plain version, and how you edited the plan;</li><li>for each step: the checks you wrote first, the teach-back, and anything you fixed or checked yourself;</li><li><strong>What I wrote or decided myself.</strong> Your spec and your tests count.</li></ul><h3 id="7-write-the-verdict-30-min" tabindex="-1">7. Write the Verdict (30 min) <a class="header-anchor" href="#7-write-the-verdict-30-min" aria-label="Permalink to &quot;7. Write the Verdict (30 min)&quot;">​</a></h3><p>On Canvas, answer the four <strong>Verdict</strong> questions in section 6 of the scorecard. This is your week 6 reflection: 150–300 words, graded on specifics (<a href="./../../assessment/rubrics.html#reflections-and-peer-reviews">reflection rubric</a>). Quote a criterion, a builder&#39;s file name, a number from a usage dashboard, the moment something surprised you.</p><blockquote><p>🔴 <strong>AI off.</strong> Write the Verdict yourself. It goes on Canvas, not in your repository.</p></blockquote><hr><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Minimum to keep up:</strong> a public Project 1 repository with <code>SPEC.md</code> and an <code>index.html</code> that opens at your GitHub Pages address, even if only one criterion passes. Week 7 Studio A opens this repository in a Codespace.</p><p><strong>Fallen behind?</strong> Tell your instructor early. To take part in week 7 meanwhile, you can copy the <a href="https://github.com/Boyu-Zhang-UOI/vc101-rescue-study-timer" target="_blank" rel="noreferrer">rescue starter</a>, a working study timer built from the example spec, into a spare repository. Your own Project 1 can catch up, and a <a href="./../../assessment/#late-work-and-grace-tokens">grace token</a> can buy you time.</p></div><hr><h2 id="stretch-optional" tabindex="-1">Stretch (optional) <a class="header-anchor" href="#stretch-optional" aria-label="Permalink to &quot;Stretch (optional)&quot;">​</a></h2><h3 id="a-run-the-other-builder" tabindex="-1">A. Run the other builder <a class="header-anchor" href="#a-run-the-other-builder" aria-label="Permalink to &quot;A. Run the other builder&quot;">​</a></h3><p>Feed your spec to the builder you didn&#39;t use in the studio, with the same prompt and the same three-prompt limit, and add a column to your scorecard.</p><h3 id="b-deploy-a-builders-version-and-compare-it-with-yours-about-1-hour" tabindex="-1">B. Deploy a builder&#39;s version and compare it with yours (about 1 hour) <a class="header-anchor" href="#b-deploy-a-builders-version-and-compare-it-with-yours-about-1-hour" aria-label="Permalink to &quot;B. Deploy a builder&#39;s version and compare it with yours (about 1 hour)&quot;">​</a></h3><ol><li>In the builder you used, export the project to GitHub (AI Studio, Lovable and v0 offer GitHub sync; check what Bolt offers). Let it create a <strong>new</strong> repository in your <strong>personal</strong> account.</li><li>Before you make that repository public, look through its files. If you see a <code>.env</code> file or anything that looks like a key, keep the repository private and ask your instructor.</li><li>Go to <a href="https://vercel.com" target="_blank" rel="noreferrer">vercel.com</a>, sign in with GitHub, choose <strong>Add New → Project</strong>, import the repository and click <strong>Deploy</strong>. (Vercel&#39;s free Hobby plan can&#39;t deploy repositories owned by a GitHub organization, so use your personal account. See the <a href="./../../TOOLS.html">Tool Handout</a>.)</li><li>Compare it with your plain version, and add your answers to the bottom of <code>docs/bake-off-scorecard.md</code>:</li></ol><table tabindex="0"><thead><tr><th>Question</th><th>Builder version</th><th>My plain version</th></tr></thead><tbody><tr><td>Number of files (ignore images)</td><td></td><td></td></tr><tr><td>Number of libraries in <code>package.json</code></td><td></td><td>0</td></tr><tr><td>Lines in the main logic file</td><td></td><td></td></tr><tr><td>Number of automated tests</td><td></td><td></td></tr><tr><td>Can you find where data is saved in under 2 minutes?</td><td></td><td></td></tr><tr><td>Pick one function. Can you explain it line by line?</td><td></td><td></td></tr><tr><td>Which acceptance criteria pass on the live site?</td><td></td><td></td></tr></tbody></table><h3 id="c-test-the-boundaries" tabindex="-1">C. Test the boundaries <a class="header-anchor" href="#c-test-the-boundaries" aria-label="Permalink to &quot;C. Test the boundaries&quot;">​</a></h3><p>Test the exact boundary of every rule with a limit: the last value accepted and the first refused. Then change a <code>&lt;=</code> to <code>&lt;</code> in <code>lib/</code> on purpose, see which test catches it, and change it back.</p><h3 id="d-get-ahead-on-week-7" tabindex="-1">D. Get ahead on week 7 <a class="header-anchor" href="#d-get-ahead-on-week-7" aria-label="Permalink to &quot;D. Get ahead on week 7&quot;">​</a></h3><p>Read <a href="./../../resources/web-basics.html">How the Web Works</a>, then find in your <code>app.js</code> where an event listener is added, where it reads <code>localStorage</code>, and where it calls <code>lib/</code>.</p>',48)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
